insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 1, 'Under PIA s.259(a)(i), which body assesses and collects the hydrocarbon tax?', '["The Nigerian Upstream Petroleum Regulatory Commission, which also sets each field''s fiscal price.", "The Authority, which regulates the midstream and downstream.", "The Federal Inland Revenue Service, which the Act calls the Service.", "The Nigerian Sovereign Investment Authority."]'::jsonb, 2, 'Section 259 opens by giving the collection of Government revenue to the Service and the Commission, and s.259(a)(i) gives the Service the assessment and collection of hydrocarbon tax. The Commission determines and collects royalties, rents and bonuses under s.259(b)(i); the Authority regulates the midstream and downstream; the Nigerian Sovereign Investment Authority is only the destination of the royalty by price.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 2, 'What does PIA s.259(b)(i) make the Commission responsible for?', '["Determining and collecting royalties, signature bonus, rents and related payments.", "Assessing companies income tax and the tertiary education tax on taxable petroleum operations.", "Collecting the development levy into a special account and sharing it among seven recipients.", "Receiving the royalty by price for a sovereign investment fund."]'::jsonb, 0, 'The text reads: "(b) the Commission shall be responsible for the determination and collection of: (i) royalties, signature bonus, rents, and related payments and its enforcement under this Act". Companies income tax and the tertiary education tax go to the Service under s.259(a)(ii); the development levy is collected by the Service under NTA s.59(2); the royalty by price is credited to the Nigerian Sovereign Investment Authority, which collects nothing.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 3, 'Where does Seventh Schedule para 11(3) send the money raised by the royalty by price?', '["Into the Federation Account, together with the production royalty and every tax.", "To the credit of the Nigerian Sovereign Investment Authority.", "Into the special account of the development levy, shared out by fixed percentages.", "Toward the host communities development trust fund of the producing area each year."]'::jsonb, 1, 'Para 11(3) reads: "(3) Royalty derived from “royalty by price” shall be for the credit of Nigerian Sovereign Investment Authority." The Federation Account is the default for money due to Government (s.258(2)), but this royalty is carved out. The levy''s special account belongs to NTA s.59(2), and the host communities trust is funded from opex under s.240(2).'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 4, 'What does PIA s.258(2) require of money collected from the petroleum industry that is due to the Government?', '["Deposit in an escrow account with a Nigerian bank before any transfer is made to Government.", "Credit to the Commission''s budget until royalties are verified.", "Retention by the Service until the NTA 2025 commences.", "Transfer to the Federation Account in a timely manner, subject to the Act."]'::jsonb, 3, 'Section 258(2) reads that such money "shall be transferred to the Federation Account in a timely manner, subject to this Act", and lists taxes, royalties, production and profit shares and bonuses among the payments. No escrow step, Commission budget or waiting period appears in the text; the escrow condition in this course belongs to a decommissioning fund, a later tier''s question.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 5, 'Under the Nigeria Tax Act 2025, which body is the relevant tax authority for the administration of royalty?', '["The Commission, which keeps the royalty role it holds under PIA s.259(b)(i) with no change at all.", "The Authority, because royalty in a year under that Act is treated as a downstream charge.", "The Service, under NTA s.89(2) and its Seventh Schedule para 1(1).", "The Nigerian Sovereign Investment Authority, for every royalty."]'::jsonb, 2, 'NTA s.89(2) makes the Service the relevant tax authority for the administration of royalty, and the Seventh Schedule para 1(1) reads: "The Service shall administer royalties payable in accordance with the provision of the Nigeria Tax Administration Act, 2025." The Nigeria Tax Act''s Seventh Schedule restates the same terrain royalty rates. The Authority has no royalty role, and the sovereign fund receives only the royalty by price.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 6, 'Which recipient takes the largest share of the development levy under NTA s.59(3)?', '["The Tertiary Education Trust Fund, at 50%.", "The Defence and Security Infrastructure Fund, which s.59(3)(f) gives 10% of the revenue.", "The Nigerian Education Loan, which s.59(3)(b) gives 15% of the levy revenue each year.", "The National Cybersecurity Fund, named last in the list of recipients at 5% of the levy."]'::jsonb, 0, 'NTA s.59(3)(a) gives the Tertiary Education Trust Fund 50%. The other shares are the Nigerian Education Loan 15%, the Defence and Security Infrastructure Fund 10%, two funds at 8%, the National Cybersecurity Fund 5% and the National Board for Technological Incubation 4%, so each distractor names a real recipient with a smaller share.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 7, 'What does NTA s.59(4) say about the development levy and the hydrocarbon tax?', '["The levy replaces the hydrocarbon tax in NTA years.", "The levy is not charged on assessable profits computed for hydrocarbon tax.", "The levy is deducted from hydrocarbon tax profit first.", "The levy reaches those profits in deep offshore years."]'::jsonb, 1, 'The text reads: "(4) The tax imposed under this Part shall not be levied on assessable profits computed for the purposes of hydrocarbon tax." So the levy reads the companies income tax base alone. It is therefore neither charged on nor deducted from the hydrocarbon tax base, and the section draws no line by terrain.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 8, 'How many provisions does this course teach, and how does the engine divide them?', '["41 provisions, every one of them computed by the engine, with 14 left out of any grade.", "27 provisions, all computed, plus 14 more that the Professional tier adds later on.", "41 provisions: 14 computed and 27 concept-only.", "41 provisions: 27 the engine computes and 14 that are concept-only."]'::jsonb, 3, 'The provision map lists 41 provisions: 27 computed and 14 concept-only. A computed provision may be graded, and only on a figure the engine returns; a concept-only provision is never computed. The 27 and 14 are one list for the whole course, and swapping them inverts which provisions the engine can compute.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 9, 'In this course, what does it mean to call the fiscal oil price the Commission sets concept-only?', '["It is minor detail that the lessons mention in passing and a learner can safely skip over.", "It is computed but withheld from the capstone.", "It is taught from its text with its citation and is never graded on a number.", "It is graded only on the Regulations base figure."]'::jsonb, 2, 'Concept-only has a legislated meaning here: taught from the text with its citation and never graded on a number. It does not mean unimportant. The engine does not compute the fiscal oil price at all (the realised price stands in for it and a note says so), so there is no engine figure to withhold or to grade on any base.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 10, 'How does the course name the Petroleum Industry Act 2021 with its edition and read date?', '["Official Gazette No. 205, Vol. 109, 22 November 2022, read on 2026-09-26 with the Act.", "Official Gazette No. 142, Vol. 108, 27 August 2021, read on 2026-09-26.", "Official Gazette No. 117, Vol. 112, 26 June 2025, read on 2026-09-26 by the course.", "Commencement 16 August 2021, read through commentary."]'::jsonb, 1, 'The texts table gives the Act as Official Gazette No. 142, Vol. 108, Lagos, 27 August 2021, with commencement on 16 August 2021, read on 2026-09-26. Gazette No. 205, Vol. 109 is the Petroleum Royalty Regulations 2022, and No. 117, Vol. 112 is the Nigeria Tax Act 2025. The Act is a primary text, quoted from the gazette.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 11, 'What does the course record about the Nigeria Tax Act 2025 text it read?', '["Effective 1 January 2026; re-gazetting ordered December 2025; no Certified True Copy read.", "Effective 26 June 2025, with a Certified True Copy read.", "Effective 1 May 2023, read as a scanned copy.", "Effective 16 August 2021, with no edition recorded."]'::jsonb, 0, 'The texts table records Official Gazette No. 117, Vol. 112, 26 June 2025, effective 1 January 2026 (a State House statement), with re-gazetting ordered in December 2025 and no Certified True Copy read. 26 June 2025 is the gazette date and no copy was certified; 1 May 2023 belongs to the Finance Act 2023; 16 August 2021 is the Act''s commencement.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 12, 'Which two values does the course say rest on a secondary source, and so states wherever they are used?', '["The development levy of 4% and the companies income tax rate of 30 percent, both from commentary on the NTA.", "The royalty by price benchmarks and the 2.5% gas rate.", "The 3% HCDT contribution and the terrain royalty rates.", "The tertiary education tax of 2.5 percent before 2023, and the NDDC levy base of the total annual budget."]'::jsonb, 3, 'Only two values rest on secondary sources: the 2.5 percent tertiary education tax before 2023 (Finance Act 2021, read through EY and Forvis Mazars alerts) and the NDDC levy base of the total annual budget (NDDC Act 2000, read through Mondaq and Lexology commentary). The levy, the income tax rate, the benchmarks, the gas rate, HCDT and the terrain rates are all read from primary gazetted texts.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 13, 'How does the course treat a model contract sold under licence, such as an AIPN model contract?', '["It quotes short clauses with their citation, as it does for the Act and the Regulations.", "It quotes the contract''s fiscal terms and leaves the operating clauses as concept-only.", "It teaches it by concept only and quotes none of it.", "It replaces it with the Act''s own wording and quotes that under the contract''s title."]'::jsonb, 2, 'The rule is that no licensed text is quoted anywhere in this course: model contracts sold under licence and paid commentary are taught by concept only. Only public texts are quoted, always with their citation, so neither short clauses nor fiscal terms of a licensed contract appear, and the Act''s words are never passed off under another text''s title.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 14, 'Where do the practicals of this course run?', '["In a Suite app for the Act, opened from the dashboard beside each lesson.", "In the course''s own calculator panels, which call the same vendored engine.", "On a spreadsheet the learner downloads and fills in by hand for each case.", "In a stored answer table that the panel looks up by the name of the case."]'::jsonb, 1, 'This is an engine course with no Suite app. The royalty calculator (Associate), the hydrocarbon tax calculator (Professional) and the ledger calculator (Expert) each call the vendored engine on the learner''s own terms and rows. Nothing is downloaded, and nothing is looked up: every figure a panel prints is computed on the inputs given.'),
  ('pia', 'beginner', 'module', 'm01-who-decides-what', 15, 'Ekene Alpha runs and the panel prints the daily rate note from kpis.pia_notes below the table. How does the course classify that run?', '["As a result: the note states a default, a conflict between texts or an approximation.", "As a refusal, because the engine had to make an approximation before it could finish.", "As a partial run, whose figures stay withheld until the learner clears the note.", "As an error that the learner fixes by changing the terrain in the case box and rerunning."]'::jsonb, 0, 'A refusal is a thrown error whose message states the exact condition that failed, and it returns no figures. A result returned with a note in kpis.pia_notes is a result: the note is course content, printed below the table, stating the engine''s annual reading of the daily rate. Nothing is withheld, and no input needs changing.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 1, 'Which three instruments does PIA s.70(1) create?', '["An oil prospecting licence, an oil mining lease and a marginal field licence for small fields that produce under the Act.", "A petroleum exploration licence, a petroleum prospecting licence and a petroleum mining lease.", "A petroleum exploration licence, an oil mining lease and a production sharing contract.", "A prospecting licence, a mining lease and a host community licence."]'::jsonb, 1, 'Section 70(1)(a) to (c) names the petroleum exploration licence, the petroleum prospecting licence and the petroleum mining lease. The oil prospecting licence and oil mining lease are the older instruments a holder may convert; s.94(9) says no new marginal fields shall be declared; a production sharing contract is concept-only in this course; and no host community licence exists.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 2, 'On what basis may a petroleum exploration licence be granted under PIA s.70(1)(a)?', '["An exclusive basis, with the right to win, work and dispose of crude oil, condensates and natural gas.", "An exclusive basis for appraisal drilling, lasting up to 10 years in deep offshore acreage.", "A production basis, holding a discovery until a lease is granted.", "A non-exclusive basis."]'::jsonb, 3, 'The text reads: "(a) petroleum exploration licence, which may be granted to qualified applicants to carry out petroleum exploration operations on a non-exclusive basis". The exclusive right to win, work and dispose of production belongs to the petroleum mining lease (s.70(1)(c)); drilling exploration and appraisal wells belongs to the prospecting licence, whose deep offshore term is up to 10 years (s.77(2)); and the exploration licence holds no discovery.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 3, 'How long may a petroleum mining lease run under PIA s.86(1)?', '["For a maximum period of 20 years, a term that includes its development period.", "Three years, renewable once for three more years.", "Not more than 10 years, the term of a frontier prospecting licence.", "18 months from the effective date, then until conversion ends."]'::jsonb, 0, 'Section 86(1) reads that the lease "shall be for a maximum period of 20 years, which term shall include the" development period. Three years renewable for three is the exploration licence (s.71(3)); 10 years is the most a deep offshore or frontier prospecting licence may last (s.77(2)); 18 months is the conversion window of s.92(4), which says nothing about a lease''s term.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 4, 'What is the longest term PIA s.77(2) allows a petroleum prospecting licence for deep offshore and frontier acreage?', '["A maximum of 20 years including the development period, the same as a mining lease under s.86(1) of the Act.", "Three years with one renewal of three more years if the prescribed conditions are met by the holder in time.", "Not more than 10 years: a five-year initial exploration period and an optional five-year extension.", "Five years with no extension, after which the acreage is relinquished."]'::jsonb, 2, 'The text reads: "(2) A petroleum prospecting licence for deep offshore and frontier acreages shall be for a duration of not more than 10 years, comprising of an initial exploration period of five years and an optional extension period of five years." Twenty years is the mining lease (s.86(1)); three plus three is the exploration licence (s.71(3)); and the five-year extension is optional, so the term is not capped at five.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 5, 'A case states pia_license_type "OML". What does the engine do with it?', '["It runs the case on the old royalty table and adds a note naming the Petroleum Profits Tax Act as the text that applies to it.", "It converts the lease to a petroleum mining lease on the s.267(a) terms and runs the case with a note about the conversion.", "It refuses, in its own words: pia_license_type must be \"PML\" or \"PPL\"; got \"OML\".", "It treats the licence as a PPL and runs the case with no message."]'::jsonb, 2, 'The engine accepts pia_license_type "PML" or "PPL" only, and a licence type from before the Act is refused with that message, the engine''s own words. It models converted and new-acreage terms only, so it neither runs an old royalty table nor performs a conversion itself (conversion is concept-only, and the lease status is a stated input), and it never substitutes another licence silently.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 6, 'Which list gives exactly the pia_terrain values the engine accepts?', '["\"onshore\", \"shallow_water\", \"deep_offshore\" and \"frontier\".", "\"onshore\", \"offshore\" and \"frontier\".", "\"onshore\", \"shallow_water\" and \"marginal_field\".", "\"land\", \"swamp\", \"shallow_water\" and \"deep\"."]'::jsonb, 0, 'The engine''s exported PIA_TERRAINS reads "onshore", "shallow_water", "deep_offshore", "frontier". The value "offshore" is refused (the message names the four accepted strings back), "marginal_field" is refused because a marginal field is onshore or in shallow water, and the texts name no land or swamp terrain.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 7, 'Why does the engine refuse pia_terrain "marginal_field"?', '["The Act abolished marginal fields in 2021, so any case that names one sits wholly outside the engine and the course.", "Marginal fields pay royalty only by price, which the terrain input has no way to express on its own.", "The engine needs a water depth to place a marginal field, and a marginal field case carries none.", "A marginal field is onshore or in shallow water."]'::jsonb, 3, 'The refusal''s first sentence reads: pia_terrain "marginal_field" is not a terrain under the Petroleum Industry Act 2021: a marginal field is onshore or in shallow water (PIA Seventh Schedule para 10(4); Petroleum Royalty Regulations 2022 r.13(2)). Producing marginal fields convert under s.94(1) and s.94(9) only stops new ones being declared; their royalty follows the terrain''s tranches; and the engine never reads the water depth at all.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 8, 'ekene_marginal_shallow_flag is a producing marginal field converted under s.94(1), in shallow water, at a 2026 daily rate of 20000.000000 bopd. Which liquids royalty rate does the engine return?', '["0.050000, the first tranche rate, which a producing marginal field keeps on every barrel it produces.", "0.093750, the shallow water tranche rate at that daily rate.", "12.5 percent, the terrain rate of shallow water, on the whole volume.", "0.106250, the onshore scale''s rate at that daily rate."]'::jsonb, 1, 'The flag pia_marginal_field_pre_2021 moves the hydrocarbon tax class and leaves the royalty on the terrain''s tranches, so the engine returns 0.093750, the shallow water rate at 20000 bopd in the tranche table. The whole volume does not pay 5 percent or the flat 12.5 percent, and 0.106250 is the onshore rate at the same daily rate, where 15 percent enters above 10,000 bopd.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 9, 'On a shallow water case, a learner changes pia_water_depth_m to a depth beyond the 200 metre line and runs it again. What moves?', '["Nothing, since the engine carries the depth in the terms and never reads it; the terrain string decides.", "The royalty, as the field is now deep offshore.", "The hydrocarbon tax, which the engine reads from the depth.", "Only the royalty by price, tied to water depth."]'::jsonb, 0, 'The engine carries pia_water_depth_m and never reads it: the terrain string alone decides the royalty and the tax. The 200 metre line lives in the texts'' description of the terrains, and a learner who wants deep offshore terms states pia_terrain "deep_offshore". The royalty by price reads the price and the terrain, and nothing reads the depth.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 10, 'How does this course treat a field lying partly in shallow water and partly in deep offshore?', '["As a computed case, in which the engine splits the field by the stated water depth and blends the two terrain rates by itself.", "The engine charges the higher of the two terrain rates on the whole volume of the field.", "As concept-only: para 10(7) sends it to a weighted average under the Regulations, which the engine does not model.", "At the frontier rate of 7.5% until reclassified."]'::jsonb, 2, 'Seventh Schedule para 10(7) sends such a field to a weighted average royalty worked out under the Regulations, which set the method in r.14(5) and (6). The engine does not model a field in two terrains, so it is taught from its text and never graded on a number. The engine never reads a depth, applies no higher-of rule and does not move such a field to frontier terms.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 11, 'Under PIA s.92(4), by when must a conversion contract be concluded?', '["The later of 18 months from the effective date and the expiry of the oil mining lease, whichever comes last.", "The earlier of 18 months from the effective date and the expiry of the oil mining lease.", "Ten years from the effective date, the longest prospecting term the Act allows for any acreage.", "Any date the holder chooses, since conversion is voluntary."]'::jsonb, 1, 'The text reads: "(4) A conversion contract shall be concluded at a date (“conversion date”) which is the earlier of: (a) 18 months from the effective date ; and (b) the expiration date of the oil mining lease". It is the earlier of the two dates. Ten years is a prospecting licence term, and although s.92(1) makes conversion voluntary, the date by which it must happen is fixed by the text.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 12, 'On conversion of an oil mining lease, what becomes of the areas selected under s.93(1)(d) and (e), those in development or regular commercial production?', '["They become petroleum prospecting licences, carried on the fiscal terms of s.267(b) for appraisal work.", "They are relinquished by the holder under s.93(4), and the acreage returns to the state for new licensing.", "Old oil mining lease terms, kept until that lease expires.", "Petroleum mining leases on the s.267(a) fiscal terms."]'::jsonb, 3, 'PIA s.93(6)(b) reads that areas "selected under subsection (1) (d) and (e), into petroleum mining leases, with fiscal terms as applicable under section 267 (a)". Areas designated for appraisal or discovery work under s.93(6)(a) become prospecting licences on the s.267(b) terms, unselected areas are relinquished under s.93(4), and a converted area leaves the old lease terms behind.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 13, 'A holder of an oil mining lease signs no conversion contract before the conversion date. What follows, and what does the engine do with such a lease?', '["Its old terms continue under s.92(6); the engine models converted and new-acreage terms only, so the case is concept-only.", "The Act applies from the conversion date, and the engine runs the lease with pia_lease_status \"new\".", "The lease is relinquished at once, and the engine refuses it.", "It pays tax at the new-lease stated rate."]'::jsonb, 0, 'PIA s.92(6) keeps the terms that applied before the effective date, and s.303(1) keeps the Act away from such a holder until the licence or lease ends or expires; the Nigeria Tax Act 2025 carries petroleum profits tax for leases yet to convert in its own Part (s.90(1)). The engine models converted and new-acreage terms only, so an unconverted lease is not run at all: the engine neither treats it as new nor gives it a stated rate.'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 14, 'In this course''s legislated words, what is a new lease?', '["Any lease signed in the last few years, whatever the acreage it covers and however it was granted.", "A petroleum mining lease granted out of new acreage, pia_lease_status \"new\".", "A petroleum mining lease converted from an oil mining lease after the Act came into force in 2021.", "A lease renewed under the Act, status \"renewed\"."]'::jsonb, 1, 'The vocabulary fixes a new lease as a petroleum mining lease granted out of new acreage (engine pia_lease_status "new"). A lease converted from an oil mining lease is a converted lease, whatever its date, and the engine refuses "renewed" in its own words: pia_lease_status must be "converted" or "new"; got "renewed".'),
  ('pia', 'beginner', 'module', 'm02-licences-leases-and-terrains', 15, 'What does PIA s.94(9) say about marginal fields?', '["Every marginal field must pay the frontier rate of royalty until it converts to a petroleum mining lease.", "Marginal fields form a fifth terrain with a royalty scale and a set of tranches of their own.", "Producing marginal fields keep their old terms indefinitely.", "No new marginal fields shall be declared."]'::jsonb, 3, 'The text reads: "(9) No new marginal fields shall be declared under this Act." A producing marginal field must convert to a petroleum mining lease within 18 months (s.94(1)); it is onshore or in shallow water and pays that terrain''s tranches, so there is no fifth terrain and no frontier rate for it, and it cannot keep its old terms indefinitely.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 1, 'A shallow water field produces 50,000 bopd. What royalty rate does the engine return on the whole liquids volume?', '["0.112500, the two tranches blended with 12.5 percent on the barrels above 10,000 bopd.", "12.5 percent, the terrain rate, since the field is well above 10,000 bopd.", "0.132500, the rate the onshore scale returns at 50,000 bopd.", "0.062500, the average of the two small-field tranches."]'::jsonb, 0, 'The engine applies the first 5,000 bopd at 5 percent, the next 5,000 at 7.5 percent and everything above 10,000 bopd at the shallow water rate of 12.5 percent, as one weighted rate on the whole volume: 0.112500. Charging 12.5 percent on every barrel ignores the tranches; 0.132500 is the onshore rate, where 15 percent enters; 0.062500 is the rate at exactly 10,000 bopd.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 2, 'A deep offshore field produces 60,000 bopd. Which rate does the engine return?', '["7.5 percent on the whole volume, since the field is past the 50,000 bopd tier.", "0.050000, since deep offshore pays 5 percent at every daily rate.", "0.054167, with 7.5 percent on only the barrels above 50,000 bopd.", "0.114583, the shallow water rate at 60,000 bopd."]'::jsonb, 2, 'Seventh Schedule para 10(3) charges 5% up to 50,000 bopd and "the share of the production above 50,000 bopd" at the terrain rate, and r.13(1)(b) makes that a weighted average: 0.054167 at 60,000 bopd. Charging 7.5 percent on the whole volume is the step error; 5 percent holds only up to and including 50,000 bopd; 0.114583 belongs to shallow water.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 3, 'An onshore field produces exactly 5,000 bopd. Which statement matches the engine?', '["It pays 0.050005, since the edge barrel falls in the 7.5 percent tranche above it.", "It pays exactly 5.000000 percent, as the first tranche includes its edge.", "It pays 6.250000 percent, the average of the two small-field tranches of the Schedule.", "It pays 15 percent, the onshore terrain rate, on every barrel."]'::jsonb, 1, 'Each edge belongs to the tranche below it: r.13(2)(a) covers "production less than or equal to 5,000bopd", so the engine returns 0.050000 at 5000 bopd. The rate 0.050005 is the engine''s figure at 5001 bopd, 6.250000 percent is the rate at 10,000 bopd, and the 15 percent terrain rate reaches only barrels above 10,000 bopd.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 4, 'At exactly 10,000 bopd the Regulations'' middle band says "less than" and the upper band "greater than". What does the engine return onshore and in shallow water?', '["0.062509 onshore and 0.062506 in shallow water, since the terrain rate begins to enter right at the edge.", "0.050000 for both terrains, because the second tranche of 7.5 percent opens only above 10,000 bopd.", "A refusal from the engine, because neither band of the Regulations covers exactly 10,000 bopd.", "0.062500 for both; the two formulas agree there, so the gap moves no figure."]'::jsonb, 3, 'r.13(2)(b) covers production "less than 10,000bopd" and r.13(2)(c) and (d) cover "greater than 10,000bopd". At exactly 10,000 bopd both formulas give 0.062500, which is what the engine returns, so the gap moves no figure. 0.062509 and 0.062506 are the engine''s figures at 10001 bopd; the second tranche starts above 5,000 bopd; and the engine does not refuse a finite daily rate of 0 or more.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 5, 'At 20,000 bopd, why does onshore pay 0.106250 while shallow water pays 0.093750?', '["Onshore reads its tranches month by month under r.12(2) while shallow water reads the whole year at once.", "Shallow water keeps the 5 percent first tranche for its first 10,000 bopd, where onshore keeps it for 5,000.", "Onshore adds a royalty by price that the shallow water scale does not carry at that price.", "Above 10,000 bopd the terrain rate enters: 15 percent onshore, 12.5 in shallow water."]'::jsonb, 3, 'Both terrains pay 5 percent on the first 5,000 bopd and 7.5 percent on the next 5,000; the barrels above 10,000 bopd pay the terrain rate of para 10(2), 15 percent onshore and 12.5 percent in shallow water, so the weighted rates part. The engine reads every terrain''s daily rate the same annual way, the tranches are identical below 10,000 bopd, and the royalty by price is a separate line that every terrain but frontier pays alike.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 6, 'What liquids royalty rate does frontier acreage pay at 1 bopd and at 120000 bopd?', '["0.050000 at 1 bopd and 0.075000 at 120000 bopd, climbing on the onshore tranches.", "5 percent up to 50,000 bopd, then 7.5 percent above that, as in deep offshore.", "0.075000 at both, because r.13(3) applies no sliding scale to a frontier basin.", "No royalty at either rate."]'::jsonb, 2, 'The Regulations read: "(3) For frontier basin, the sliding scale shall not apply and the applicable rate shall be 7.5%." The engine returns 0.075000 at every daily rate in its tranche table. Frontier follows neither the onshore tranches nor the deep offshore tier, and what frontier escapes is the royalty by price (para 11(2)); its production royalty is still charged.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 7, 'Ekene Alpha''s 2026 rows carry 2920000 barrels of oil and 116800 of condensate. Why does the condensate enter the daily rate?', '["Condensate sells at the oil price, so the engine merges the two streams into one before rating.", "Para 6 treats condensates as crude oil for royalty, and r.12(1)(b) scales the total.", "Condensate is a natural gas liquid and joins the daily rate of the gas royalty.", "The engine counts every liquid, NGL included, in the daily rate the tranches read."]'::jsonb, 1, 'Seventh Schedule para 6 reads that "for royalty purposes condensates shall be treated as crude oil and natural gas liquids shall be treated as natural gas", and r.12(1)(b) applies the sliding scale "to the total production of crude oil plus condensates". Alpha''s condensate sells at 70 against oil at 75, so the prices differ; natural gas liquids go with gas and stay out of the daily rate; and gas has no daily rate at all.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 8, 'Alpha 2026: crude plus condensate over the 365 days of the year. Which daily rate and liquids royalty rate does the engine return?', '["8320.000000 bopd, and a weighted liquids royalty rate of 0.059976.", "8320.000000 bopd, with 5 percent on the whole volume.", "7321.600000 bopd, and a rate of 0.057927.", "8320.000000 bopd, at the terrain rate of 12.5 percent."]'::jsonb, 0, 'The engine divides 2920000 plus 116800 barrels by 365 and returns 8320.000000 bopd, between 5,000 and 10,000 bopd, so the rate is a weighted blend of the two small-field tranches, 0.059976. Five percent applies only at or below 5,000 bopd, 12.5 percent only to barrels above 10,000 bopd, and 7321.600000 and 0.057927 are Alpha''s 2027 figures.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 9, 'How does the engine turn Ekene Alpha''s 2028 crude and condensate into the daily rate the tranches read?', '["It divides by 365 in every year, the length the engine assumes for any year of assessment it reads.", "It divides each month by the days oil was produced and rounds to whole barrels, month by month.", "It divides the year''s liquids by 366, the calendar days of 2028, giving 6425.404372 bopd.", "It takes the busiest month of the year, since the text reads a month''s production."]'::jsonb, 2, 'The engine divides the year''s crude oil plus condensate by calendarDays of the year, 366 in 2028, and prints 6425.404372 as royalty_liquids_bopd. It does not use 365 in a leap year. Month by month over the producing days, rounded, is the Regulations'' own method (r.12(2)), which the engine''s daily rate note names beside its annual reading, and no single month is picked.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 10, 'How does Regulations r.12(2) define barrels of oil per day?', '["A month''s production over the days oil was produced that month, rounded to whole barrels.", "A year''s production over the calendar days of that year, kept to six decimals.", "A month''s production over the calendar days of the month, with no rounding.", "A year''s production over the days of the year on which oil was produced."]'::jsonb, 0, 'The text reads that barrels of oil per day are found "by taking the total production for the applicable month and dividing this amount with the number of days during which oil was produced in such month, and the result shall be rounded to entire barrels." A year over its calendar days is the engine''s stated annual reading; the Regulations use producing days, a month and whole barrels.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 11, 'A shallow water gas field states pia_gas_in_country_share_pct 50. What gas royalty rate does the engine return, and in which terrains?', '["2.5 percent, because any gas used in-country earns the lower rate on the whole volume of gas produced.", "0.037500 in every terrain: half at 5 percent, half at 2.5.", "0.037500 in shallow water only, with 5 percent onshore and offshore on the remainder of the gas.", "0.043750, with a quarter of the gas put at the lower rate."]'::jsonb, 1, 'The engine blends 5 percent and 2.5 percent by the stated in-country share, and every terrain pays the same gas rate: 0.037500 at 50 percent. The lower rate applies only to the share used in-country, the terrain moves nothing in the gas royalty, and 0.043750 is the engine''s rate at a 25 percent share.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 12, 'What does Regulations r.16(4) say about natural gas liquids produced separately?', '["They pay 2.5% when they are used in-country, the same as marketable natural gas under r.16(1)(a).", "They count as condensate for royalty and pay the liquids tranche rate of the field''s terrain.", "They pay no production royalty at all and are charged a royalty by price.", "They pay 5% whether used in-country or exported."]'::jsonb, 3, 'The text reads: "(4) The royalty rate of natural gas liquids produced separately, shall be 5% regardless of whether the natural gas liquids are used in-country or exported." Only marketable natural gas used in-country earns 2.5% (r.16(1)(a)). Para 6 puts natural gas liquids with natural gas, so they never join the liquids tranches, and the royalty by price reaches crude oil and condensate only.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 13, 'ekene_nag_gas_in_country_half produces 20000000 Mscf of gas a year and no crude oil or condensate. Which royalty lines does it pay?', '["Only the gas royalty, 2250000.000000 USD a year, with no liquids royalty and no royalty by price.", "The gas royalty and a royalty by price read at the gas price of 3 USD per Mscf each year.", "The gas royalty plus a liquids royalty at 0.050000 on its condensate.", "No royalty, as a gas field is outside the Act''s royalty."]'::jsonb, 0, 'The engine returns a gas royalty of 2250000.000000 USD in each of 2026, 2027 and 2028 at 0.037500, and a liquids royalty and royalty by price of 0.000000: the field sells no crude oil or condensate, and the royalty by price reaches only those two. The 0.050000 on its row is the rate at a zero daily rate, charged on no liquids value, and para 10(6) charges gas a production royalty.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 14, 'A learner types an in-country gas share of 100.5 into the royalty calculator. What does the panel print?', '["A rate of 0.025000, with the share capped at 100 and a note in kpis.pia_notes explaining the cap.", "A result at the default share of 0, applied silently with a gas rate of 0.050000.", "The engine''s refusal: pia_gas_in_country_share_pct must be a number from 0 to 100; got 100.5.", "Negative gas royalty, shown as a credit."]'::jsonb, 2, 'deriveGasRoyaltyRate refuses a share outside 0 to 100 and the panel shows the engine''s own words. The engine does not cap, default or extrapolate this input: 100 is the highest share it accepts, where the rate is 0.025000, and a share above 100 is refused with that message.'),
  ('pia', 'beginner', 'module', 'm03-royalty-by-terrain', 15, 'Ekene Alpha''s daily rate in 2030 is 4989.463014 bopd. Which liquids royalty rate does it pay that year?', '["0.052954, the rate of 2029, carried over into the next year until the field falls further.", "Exactly 5 percent, 0.050000, at or below 5,000 bopd.", "0.059976, the rate of its first year, held for the life of the converted lease.", "12.5 percent, the terrain rate for small fields."]'::jsonb, 1, 'At or below 5,000 bopd onshore and shallow water pay exactly 5 percent, so from 2030 Alpha''s rate is 0.050000. Each year''s rate reads that year''s daily rate, so neither 0.052954 (2029) nor 0.059976 (2026) carries over, and the 12.5 percent terrain rate applies only to barrels above 10,000 bopd.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 1, 'On the Regulations base, the engine default, what are the three royalty by price benchmarks in 2025?', '["55.200000, 110.400000 and 165.610000 USD/bbl, the 2025 levels escalated from 2020.", "50.000000, 100.000000 and 150.000000 USD/bbl, fixed by the Act for every year.", "54.120000, 108.240000 and 162.360000 USD/bbl.", "54.12, 108.00 and 162.36, as printed."]'::jsonb, 2, 'On the Regulations base, 50, 100 and 150 apply to 2021 and rise by 2 percent of the previous year''s benchmark from 1 January 2022, giving 54.120000, 108.240000 and 162.360000 in 2025. The first distractor is the Act base, a different stated reading; the unescalated levels hold only up to the base year; and the printed middle figure of 108.00 is the Schedule''s misprint, which the engine does not follow.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 2, 'At 75 USD/bbl in 2025 the royalty by price rate depends on the base year, an open reading. Which pair gives both readings as the engine returns them?', '["0.019290 on the Regulations base, and 0.017935 on the Act base.", "0.017935 on the Regulations base, and 0.019290 on the Act base.", "0.025000 on both bases, the figure of the Act''s own example.", "0.019290 on both bases, as the readings agree between the benchmarks."]'::jsonb, 0, 'The engine returns 0.019290 on the Regulations base and 0.017935 on the Act base, whose higher benchmarks put 75 lower on the scale. Swapping them reverses the bases; 0.025000 is the rate at 75 in 2020, before either base escalates; and between the benchmarks the two readings differ, agreeing only at or below both low benchmarks or at or above both high ones.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 3, 'On the Regulations base in 2025, a price of exactly 108.240000 USD/bbl gives which royalty by price rate?', '["0.048043, reading the same price against the Act''s higher 2025 benchmarks on the other base.", "0.100000, since the price is above the Act''s printed middle level of 100 USD per barrel.", "0.060865, the rate the engine returns for a 2025 price of 120 on this base.", "0.050000, 5 percent at the middle benchmark."]'::jsonb, 3, '108.240000 is the Regulations'' middle benchmark for 2025, where the rate is exactly 5 percent: 0.050000. The Act base returns 0.048043 at that price, a different stated reading; the escalated middle benchmark has replaced 100; and 0.060865 is the rate at 120 USD/bbl on the Regulations base.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 4, 'Which description matches how the engine reads the royalty by price between its benchmarks?', '["A step of 0, 5 or 10 percent, whichever band the price falls in, with no rise inside a band.", "0 at or below the low benchmark, 5 percent at the middle, 10 percent at or above the high, linear between.", "A curve that doubles the rate for every 50 USD/bbl the price rises above the low benchmark.", "Straight from 0 at a price of zero to 10 percent at the high benchmark."]'::jsonb, 1, 'The engine''s rule is three points joined by straight lines: 0 at or below the low benchmark, 5 percent at the middle and 10 percent at or above the high. The NTA restatement names the method "on linear interpolation". A step jumps between bands and a line from a price of zero starts too low, so neither of them, nor a doubling curve, returns the Act''s own example of 2.5% at 75 USD/bbl in 2020, which the engine reproduces as 0.025000.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 5, 'The Act''s own example puts the royalty by price at 2.5% for 75 USD/bbl in 2020. What does the engine return?', '["0.025000 on the Act base only; the Regulations base returns 0.019290 for 2020.", "0.025000 whichever of the two base years the run states.", "0.017935 on both bases, because the benchmarks already escalate from 2020.", "A refusal, as 2020 precedes the Regulations."]'::jsonb, 1, 'The engine returns 0.025000 at 75 USD/bbl in 2020 on the Act base, and also 0.025000 on the Regulations base, which keeps the 2021 levels of 50, 100 and 150 for 2020. The rate 0.019290 is 75 in 2025 on the Regulations base, 0.017935 is 75 in 2025 on the Act base, and the engine refuses no year: before its base year each base keeps 50, 100 and 150.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 6, 'How do the royalty by price benchmarks escalate?', '["By 2% of the previous year''s benchmark every 1 January, rounded to whole cents each year.", "By 2% of the base-year level each year, on a straight line kept with no rounding at all.", "By the year''s inflation rate, which each case states among its escalators.", "By 2 USD per barrel a year on each of the benchmarks."]'::jsonb, 0, 'Both texts escalate by 2 percent relative to the previous year''s values, and the Regulations'' Schedule adds "The results shall be rounded to entire US $ cents." The engine rounds year by year, so the table must be built one year at a time. A straight line on the base level ignores the compounding, the case escalators move prices and costs, and a flat 2 USD step is the pattern of the Schedule''s misprinted middle row.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 7, 'The Regulations'' printed table gives the middle benchmark as 104.00 for 2023. What does the engine use for that year on the Regulations base?', '["104.00, since the gazetted table outranks the escalation rule that precedes it in the Schedule.", "106.120000, the Act base value for 2023, so that the two texts line up with each other.", "102.000000, carrying the 2022 value until the table and the rule agree with each other.", "104.040000, applying the 2 percent rule."]'::jsonb, 3, 'The Schedule prints the middle column as 102.00, 104.00, 106.00, 108.00 and 110.00 for 2022 to 2026, which does not follow its own 2 percent rule. The engine applies the rule, giving 104.040000 for 2023, and names the conflict in a note on every ledger with a year of 2023 or later. The printed table does not outrank the rule in the engine, 106.120000 is the Act base in 2023, a different reading, and nothing is carried from 2022.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 8, 'Read down the benchmark table on both bases. Which relationship does the course check for every year it prints?', '["The Act base in any year equals the Regulations base one year earlier than it.", "They differ by 2 USD/bbl on every benchmark.", "The Act base in any year equals the Regulations base one year later.", "The two bases agree from 2025 onward."]'::jsonb, 2, 'The Act starts the levels in 2020 and escalates from 1 January 2021; the Regulations start them in 2021 and escalate from 1 January 2022. So the Act base runs one year ahead: its 2025 levels, 55.200000, 110.400000 and 165.610000, are the Regulations'' 2026 levels. The gap is a year of escalation, which is a percentage, and it never closes.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 9, 'Frontier acreage sells oil at 120 USD/bbl in 2026 (ekene_frontier). What royalty by price does the engine return?', '["0.000000, since para 11(2) gives frontier acreages no royalty by price.", "The full 10 percent, as 120 USD/bbl clears the high benchmark.", "0.060865, the 2025 rate at 120 on the Regulations base.", "7.5 percent, the frontier rate read against price."]'::jsonb, 0, 'Seventh Schedule para 11(2) reads: "(2) There shall be no royalty by price for frontier acreages." The engine returns 0.000000 on ekene_frontier, with a liquids royalty rate of 0.075000. 120 is below the 2026 high benchmark on either base anyway, 0.060865 is what another terrain pays in 2025 on the Regulations base, and 7.5 percent is frontier''s production royalty rate on volume.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 10, 'Crude sells at 95 and condensate at 88 USD/bbl in 2025, on the Regulations base. Which royalty by price rates does the engine charge?', '["0.037768 on both, since condensate counts as crude oil for royalty.", "0.036051 on crude and 0.029710 on condensate, the rates on the Act base.", "0.037768 on crude oil and 0.031301 on condensate.", "One rate at the volume-weighted price of the two streams together."]'::jsonb, 2, 'The royalty by price is charged on crude oil and on condensate, each rated at its own price: on the Regulations base 0.037768 at 95 and 0.031301 at 88. Para 6 merges condensate with crude for the daily rate of the production royalty, and that merging stops at the volume. 0.036051 and 0.029710 are the Act base, a different stated reading than the one the question sets.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 11, 'On that same 2025 case, how much royalty by price does the engine return on each base?', '["20694235.033259 USD on either base, since both readings agree for every price above 54.120000.", "19738586.956522 USD on the Regulations base, and 20694235.033259 USD on the Act base instead.", "69663505.866593 USD on the Regulations base alone.", "Regulations reading 20694235.033259 USD; Act reading 19738586.956522 USD."]'::jsonb, 3, 'The engine returns 20694235.033259 USD on the Regulations base and 19738586.956522 USD on the Act base, whose higher benchmarks charge less. The readings differ between the benchmarks, so they do not agree at these prices, and 69663505.866593 USD is the case''s total royalty on the Regulations base, production royalty included.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 12, 'Ekene Alpha sells oil at a flat 75 USD/bbl. On the Regulations base, why does its royalty by price rate fall from 0.017935 in 2026 to 0.010320 in 2032?', '["The field''s daily rate declines each year, and the royalty by price reads that daily rate as well.", "The benchmarks escalate each year, so a constant price sits lower on the scale.", "The rate steps down a fixed amount a year under a schedule of the Nigeria Tax Act 2025.", "Condensate''s falling share pulls the rate down."]'::jsonb, 1, 'The benchmarks rise by 2 percent a year while Alpha''s price stays at 75, so each year the price sits closer to the low benchmark and the rate falls, from 0.017935 in 2026 to 0.010320 in 2032. The royalty by price reads price and year and leaves the daily rate alone; the NTA restates the same escalation; and the oil rate printed is for oil alone.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 13, 'A case states pia_price_royalty_base "act_2021". What happens when it runs?', '["It runs on the Act base, since the string names the Act and a year close to the Act''s own base year.", "It runs on the Regulations base, the default, with a note about the unknown string.", "The engine refuses: pia_price_royalty_base must be \"regulations_2021\" or \"act_2020\"; got \"act_2021\".", "No royalty by price for any year, at a zero rate."]'::jsonb, 2, 'The engine accepts exactly two base strings, "regulations_2021" (the default) and "act_2020", and refuses anything else with that message, in its own words. It does not guess a base from a near miss, it does not fall back to the default with a note, and a refusal returns no ledger at all.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 14, 'Which products carry a royalty by price?', '["Only the two liquids para 11(1) names: crude oil and condensates.", "Crude oil, condensate and natural gas liquids, all at the oil price.", "Every product the lease sells, gas included, at one blended price.", "Crude oil only."]'::jsonb, 0, 'Para 11(1) charges "a royalty by price with respect to crude oil and condensates", and the engine rates each at its own price. Natural gas liquids are treated as natural gas for royalty, gas pays no royalty by price, and condensate is charged beside crude.'),
  ('pia', 'beginner', 'module', 'm04-royalty-by-price', 15, 'How does this course handle a graded figure that depends on the royalty by price?', '["It grades the Act base as the law, because an Act of the National Assembly outranks the Regulations made under it.", "It grades the Regulations base as the law, as the later text.", "It averages the two bases.", "It states the Regulations base as the reading and grades no base against the other."]'::jsonb, 3, 'The base year is one of three open readings: taught side by side and never graded as the law. A figure that depends on it names the Regulations base, the engine default, as a stated reading for the run, and the Act base is taught beside it. Neither text is ranked as the law, and the engine computes no average of the two.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 1, 'In what order does the engine apply the instruments within one year?', '["The two taxes first, then royalty on what is left, then the contributions.", "Royalties off revenue first, then HCDT and the NDDC levy on their own bases, then the two taxes, then the education charge.", "HCDT and the NDDC levy first, then royalty on the revenue left after them.", "Companies income tax first, then the hydrocarbon tax on the profit left after it has been paid."]'::jsonb, 1, 'Royalty comes off revenue first; HCDT and the NDDC levy are computed on their own bases; the hydrocarbon tax and companies income tax are charged on their own profits; and the tertiary education tax or development levy reads the companies income tax assessable profit. Royalty reads value and comes before any tax, the contributions read cost bases and never shrink the royalty base, and companies income tax does not deduct the hydrocarbon tax, nor the reverse.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 2, 'What does PIA s.302(5) say about the two taxes on profit?', '["Companies income tax is deductible in computing the hydrocarbon tax for the same year of assessment.", "Each tax is deductible against the other in alternate years, to smooth the burden over the life.", "The hydrocarbon tax is deductible only in years under the Act alone.", "The hydrocarbon tax is not deductible in determining companies income tax."]'::jsonb, 3, 'The text reads: "(5) In determining the companies income tax, the hydrocarbon tax under this Act shall not be deductible." The reverse deduction is barred too: s.264(l) keeps companies income tax and the tertiary education tax out of the hydrocarbon tax base. The Act has no alternating rule and draws no line by framework here.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 3, 'Which amounts does PIA s.264(l) keep out of the hydrocarbon tax base?', '["The tertiary education tax, companies income tax and similar income or profits taxes.", "Royalties paid on crude oil and associated gas in the period.", "Contributions to a host communities development trust.", "The NDDC levy on the company''s total annual budget."]'::jsonb, 0, 'Section 264(l) lists "amounts incurred in respect of tertiary education tax, companies income tax, any income tax, profits tax or other similar taxes, whether charged within Nigeria or elsewhere". Royalties are deductible under s.263(1)(b), and s.263(1)(h) makes contributions to host communities development trusts and to the Niger Delta Development Commission deductible.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 4, 'The worked example states a prior-year opex of 170000000 USD. What HCDT does the engine return for 2025?', '["15000000.000000 USD, the fixed sum the case states for its NDDC levy in the same year of assessment.", "Nothing, since HCDT reads only the capex of the year it is charged in and 2025 carries none.", "5100000.000000 USD, 3 percent of the preceding year''s opex.", "3 percent of the year''s gross revenue under s.240(2)."]'::jsonb, 2, 'PIA s.240(2) sets the contribution at "an amount equal to 3% of its actual annual operating expenditure of the preceding financial year", and the first ledger year reads the stated pia_prior_year_opex_usd: 3 percent of 170000000 USD is 5100000.000000 USD. The 15000000.000000 USD is the fixed NDDC sum, and HCDT reads neither capex nor revenue.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 5, 'Why is Ekene Alpha''s 2026 HCDT 0.000000 USD?', '["Alpha states no prior-year opex, and the first ledger year reads that stated figure.", "HCDT is charged only in years under the Act alone.", "Heavy capex in 2026 cancels the contribution.", "HCDT starts after the first year of production under s.257(1) of the Act."]'::jsonb, 0, 'The first ledger year reads the stated pia_prior_year_opex_usd, 0 if none is stated, and Alpha states none; from 2027 HCDT reads the previous year''s opex, 720000.000000 USD a year. HCDT is charged in every framework, capex does not enter it, and s.257(1) makes the payment deductible, which says nothing about when it starts.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 6, 'Ekene Alpha''s 2026 NDDC levy is 4320000.000000 USD. Which base produced it?', '["3 percent of the year''s opex alone, the base that the Petroleum Industry Act 2021 sets for the levy.", "3 percent of the preceding year''s opex, the same base HCDT reads under s.240(2).", "A fixed sum stated in the case, as in the worked example.", "3 percent of the total annual budget, opex plus capex, a base read from a secondary source."]'::jsonb, 3, 'The engine takes the NDDC levy as 3 percent of the year''s opex plus capex, the total annual budget of the NDDC Act 2000 s.14(2)(b) as amended, read from a secondary source: 24000000 plus 120000000 USD gives 4320000.000000 USD. The opex base is a stated alternative that Alpha does not state, the PIA does not set this levy, HCDT is the line on preceding opex, and Alpha states no fixed sum.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 7, 'On ekene_nddc_opex_base in 2026, which pair of NDDC figures does the engine return on the two bases?', '["2250000.000000 USD on the opex base and 450000.000000 USD on the total budget.", "450000.000000 USD on the opex base and 2250000.000000 USD on the total budget.", "2250000.000000 USD on both bases, as the levy reads the whole budget whichever base is stated.", "450000.000000 USD on both bases, since capex never enters the NDDC levy."]'::jsonb, 1, 'The engine returns 450000.000000 USD on the stated opex base and 2250000.000000 USD on the default total budget in 2026, a year with capex. Swapping them reverses the bases, and the two figures differ in 2026 because the total budget counts that year''s capex while the opex base does not.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 8, 'A learner states pia_nddc_levy_base "budget". What does the panel print?', '["A ledger on the total budget base, since \"budget\" is close enough to the default string to be read as it.", "A ledger with the NDDC levy set to zero and a note naming the unknown base.", "The engine''s refusal: pia_nddc_levy_base must be \"total_budget\" or \"opex\"; got \"budget\".", "The opex base, chosen without a message."]'::jsonb, 2, 'Two NDDC bases exist in the engine, the total annual budget (the default, from a secondary source) and opex, plus a fixed sum that replaces the percentage. A string outside that pair stops the run, and the panel shows the message verbatim as the engine''s own words. Guessing the nearest base, zeroing the levy or picking the opex base would each hide a bad input behind a figure.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 9, 'Which education charge does a year under the Nigeria Tax Act 2025 carry, and on what base?', '["The tertiary education tax at 3 percent, charged on the hydrocarbon tax chargeable profit of the year.", "Both the tertiary education tax and the development levy, charged side by side on the same base.", "The development levy, 4% of the companies income tax assessable profit.", "The development levy, on the hydrocarbon tax assessable profit."]'::jsonb, 2, 'NTA s.59(1) charges "A development levy of 4%" on assessable profits, and the engine charges it on the companies income tax assessable profit. NTA s.59(4) keeps it off assessable profits computed for hydrocarbon tax, and NTA s.197(5) deletes the charging sections of the Tertiary Education Trust Fund Act, so the two charges never sit on the same year.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 10, 'The worked example is 2025, a year under the Act alone, on the default Regulations base. What tertiary education tax does the engine return?', '["Nothing, because the development levy of 4 percent is charged in that year of assessment.", "31747249.445676 USD at 2.5 percent, the rate that rests on a secondary source.", "3 percent of the hydrocarbon tax chargeable profit of 2025.", "31747249.445676 USD, at 3.000000 percent."]'::jsonb, 3, 'In a year under the Act alone the education charge is the tertiary education tax, 3.000000 percent from 2023 under the Finance Act 2023 s.26, on the companies income tax assessable profit: 31747249.445676 USD. The development levy belongs to years under the Nigeria Tax Act 2025, 2.5 percent is the rate before 2023, and the base is the income tax profit.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 11, 'Which provision removes the tertiary education tax from every ledger row read as nta_2025?', '["NTA s.197(5) deletes sections 1, 2 and 3(3) of the Tertiary Education Trust Fund Act 2011.", "The Finance Act 2023 set the tax to zero with effect from 1 May 2023.", "NTA s.59(4) exempts all petroleum operations from education charges.", "The Service stopped assessing it under PIA s.259(a)(ii)."]'::jsonb, 0, 'The text reads: "(5) The Tertiary Education Trust Fund (Establishment, Etc.) Act, 2011 is amended by deleting sections 1, 2, and 3(3)." The Finance Act 2023 raised the tax to 3 percent from 1 May 2023; s.59(4) only keeps the development levy off hydrocarbon tax profits; and s.259(a)(ii) still gives the Service the tax in a year under the Act alone.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 12, 'How does the shared fiscal wording define government take?', '["Total tax over revenue, taken year by year and then discounted at 10 percent nominal back to the ledger''s base year.", "Government cash flow over revenue less opex, with capex added back to the contractor side.", "Government cash flow over the pre-take net cash flow, revenue less opex less capex, over the project life.", "The highest marginal rate that any barrel meets in any year of the lease."]'::jsonb, 2, 'fiscalConventions.js reads that government take is "Government cash flow divided by the project''s pre-take net cash flow, which is revenue less opex less capex, over the project life." Adding capex back is the definition of the second metric, the government share of net revenue. The engine''s take is undiscounted, and it is a share of value; a marginal rate describes something else.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 13, 'On the Regulations base, the engine default, Ekene Alpha''s government cash flow is 556475163.954050 USD over a pre-take value of 835989167.000000 USD. What take does the engine report?', '["66.564877 percent, discounted at 10 percent nominal to the first year of the ledger.", "66.564877 percent, undiscounted and nominal.", "The take equals the royalties over revenue, since royalty is the first line of the stack.", "The ratio of total tax to net cash flow."]'::jsonb, 1, 'The engine''s take is government cash flow over revenue less capex less opex, undiscounted and nominal: 66.564877 percent on Alpha, which the government cash flow over the pre-take value reproduces. The discount rate of 10 percent is used for NPV and plays no part in the take, and the take counts every royalty, contribution and tax.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 14, 'At a 50 percent working interest, what does the engine return for Ekene Alpha''s money lines and take? The run keeps the default Regulations base.', '["The royalty tranches are re-read at half the daily rate, so royalties fall by more than half.", "The money lines stay at field level, and the take alone is scaled to the share.", "Taxes halve while the royalties stay whole, so the take rises.", "Every money line is half, and the take holds at 66.564877."]'::jsonb, 3, 'The engine reads the tranches, caps and every rate at field level, then scales each money line to the share: at 50 percent every money line is half (checked) and the take does not move (checked), 66.564877 on both. The daily rate is never re-read at the share, the money lines are the ones scaled, and royalties halve with the taxes.'),
  ('pia', 'beginner', 'module', 'm05-the-instruments-stacked', 15, 'Ekene Alpha sells associated gas. Why does the engine deduct none of Alpha''s gas royalty in the hydrocarbon tax base?', '["Gas royalty is deducted only in companies income tax years under the Act alone.", "Gas sits outside the hydrocarbon tax, so its royalty has nothing to reduce there.", "The gas royalty is paid by the buyer of the gas, so it never reaches the lease''s ledger.", "NTA s.59(4) keeps every royalty out of hydrocarbon tax profits."]'::jsonb, 1, 'The hydrocarbon tax charges crude oil and condensate only, so its base deducts the liquids production royalty and the royalty by price and leaves the gas royalty out. Costs shared with gas enter that base at the crude-plus-condensate share of gross revenue, 0.970075 on Alpha, a stated approximation. The gas royalty is on Alpha''s ledger and in its total royalty, and s.59(4) speaks of the development levy.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 1, 'What is every graded number in this course?', '["A return value of the engine on fixed terms and rows written down in advance.", "A figure the lesson prints, rounded by the grader to two decimals before it is compared.", "A figure the Commission publishes for the year of the case.", "A value from the stdlib oracle''s golden file."]'::jsonb, 0, 'Every capstone field, question key and panel figure is read from computeCashFlow or one of its rate functions on terms and rows fixed in advance, so the same inputs give the same number on any machine and there is exactly one right answer. The oracle''s golden expected figures are provenance, the Commission publishes nothing the engine reads, and a lesson sentence is never the source of a key.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 2, 'A lease is run under each open reading in turn. What happens to its graded fields?', '["It is graded on the Act base.", "Graded twice, once under each stated reading of the base year.", "They are identical under every reading of all three.", "It is graded on the learner''s reading."]'::jsonb, 2, 'The course proves each graded field identical whichever answer a run gives to the base year, the new-lease rate onshore or in shallow water, or the deep offshore rate under the Nigeria Tax Act 2025, so the grade decides none of those questions. Grading one reading, grading twice or grading the learner''s own choice would each turn an open question into a scored answer.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 3, 'The worked example carries 18250000 barrels of oil in 2025 in shallow water. Which daily rate and liquids royalty rate does the engine return?', '["50000.000000 bopd and 12.5 percent, the shallow water terrain rate, charged on every barrel.", "50000.000000 bopd and 0.112500, the course''s 11.250000 percent.", "50000.000000 bopd and 0.132500, the weighted rate of the onshore scale.", "50000.000000 bopd and 0.062500, the edge rate."]'::jsonb, 1, '2025 has 365 calendar days, so 18250000 barrels give 50000.000000 bopd, and at that rate in shallow water the weighted rate is 0.112500, which the course writes as 11.250000 percent. The terrain rate reaches only the barrels above 10,000 bopd, 0.132500 is the onshore rate, and 0.062500 is the rate at exactly 10,000 bopd.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 4, 'What 2025 liquids production royalty does the engine return on the worked example?', '["199158351.810791 USD, which is the total royalty with the royalty by price included.", "34908351.810791 USD, which is the royalty by price for the year on the Regulations base.", "182500000 USD, which is the year''s opex from the same case rows.", "164250000.000000 USD."]'::jsonb, 3, 'The liquids production royalty is 164250000.000000 USD. 199158351.810791 USD is the total royalty, which adds the royalty by price of 34908351.810791 USD read on the Regulations base, and 182500000 USD is the opex row of the case.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 5, 'The worked example sells oil at 80 in 2025 and states no base year. What oil rate does its price royalty line use?', '["0.022464, read on the Regulations base, the engine default.", "0.023910, read on the Act base.", "0.023910, read on the Regulations base.", "0.025000, the rate of the Act''s example."]'::jsonb, 2, 'The worked example states no base, so it runs on the Regulations base, the engine default, and returns 0.023910 at 80 USD/bbl in 2025. The Act base returns 0.022464 at the same price, a different stated reading, and 0.025000 is the Act''s example at 75 USD/bbl in 2020.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 6, 'On the Regulations base, Ekene Alpha''s 2026 total royalty is 18012822.226867 USD. Which lines make it up?', '["Liquids production royalty plus gas royalty plus royalty by price.", "The liquids production royalty and the royalty by price.", "The production royalties, HCDT and the NDDC levy.", "Only the liquids royalty, as gas is outside it."]'::jsonb, 0, 'Royalty in this course means the production royalty on liquids and gas plus the royalty by price, the engine''s total royalty. In 2026 its parts are the liquids royalty of 13625099.038462 USD, the gas royalty of 350400.000000 USD and the royalty by price of 4037323.188406 USD on the Regulations base. Gas is outside the hydrocarbon tax, but it is inside royalty, and HCDT and the NDDC levy are contributions.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 7, 'In the royalty calculator''s first royalty table, what does the production royalty column hold?', '["The liquids royalty, the gas royalty and the royalty by price, which is the engine''s total royalty line.", "The royalty on crude oil alone, with condensate and gas shown in two other columns.", "The royalty by price, which is the production royalty''s price-linked part.", "The royalties on liquids and gas added together."]'::jsonb, 3, 'The production royalty is the royalty on liquids plus the royalty on gas; the royalty by price has a column of its own beside it. Adding the royalty by price gives the total royalty; condensate is rated with crude oil; and the royalty by price is a separate royalty on crude oil and condensate.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Ekene Alpha''s first royalty table prints a 2027 gas royalty of 308352.000000 USD. Which gas rate produced it, and why?', '["0.037500, with half of Alpha''s associated gas used in-country, as on the gas field case.", "0.050000, as the case states no in-country gas share.", "0.057927, the 2027 liquids royalty rate applied to the associated gas as well.", "0.025000, the in-country rate."]'::jsonb, 1, 'Alpha states no pia_gas_in_country_share_pct, so the default share of 0 applies and its gas pays 0.050000 in every year. 0.037500 belongs to the gas field case, which states a 50 percent share; the liquids tranche rate never reaches gas, which pays under para 10(6); and 0.025000 is the rate only at a 100 percent in-country share.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Before copying a figure off the panel for a stated year, what should a learner check?', '["That the figure is rounded to two decimals.", "That the row is the year named and its framework is the expected one.", "That the take tile is above 50 percent.", "That the panel printed no notes at all, since a note means the figure is only an approximation of the true value."]'::jsonb, 1, 'The capstone brief says to check that a figure''s row is the year the card names and that the year''s framework is the one expected. Every value is reported to six decimals, the take is whatever the engine returns, and a note in kpis.pia_notes accompanies a result without making it any less the engine''s return value.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 10, 'A capstone asks for a money value on a lease at a stated working interest. On what footing is that value reported?', '["At 100 percent field level, whatever working interest the case states for the lease.", "At half the field figure, as the Ekene practice case at 50 percent is the standard case.", "At the government''s share of the profit.", "At the working interest share."]'::jsonb, 3, 'Every money figure is at the working interest share: the engine runs the tranches, the caps and every rate at field level, then scales every money line to the stated share. Rates are read at field level, the 50 percent case is one practice case among several, and the government''s share of value is what the take measures.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What 2025 total tax does the worked example return on the Regulations base, and which lines does it add?', '["617004738.359202 USD, from the hydrocarbon tax, the income tax and the education tax.", "617004738.359202 USD: every royalty plus the hydrocarbon tax and companies income tax.", "285784994.456763 USD: the hydrocarbon tax alone.", "299472494.456763 USD: companies income tax alone."]'::jsonb, 0, 'The engine''s total tax for 2025 is 617004738.359202 USD, the hydrocarbon tax plus companies income tax plus the tertiary education tax (checked). Royalties sit on their own line outside total tax, and 285784994.456763 USD and 299472494.456763 USD are the hydrocarbon tax and companies income tax on their own.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 12, 'For 2027 the practice run prints 7321.600000 in the bopd column. What sits beside it in the liquids rate column?', '["0.059976, Alpha''s 2026 rate, held for the life of the lease.", "0.055546, the rate the engine returns for 2028.", "0.057927, weighted between the two tranches.", "5 percent, the rate of the first tranche."]'::jsonb, 2, 'Each year reads its own daily rate: 7321.600000 bopd sits between 5,000 and 10,000 bopd, so 2027 pays a weighted 0.057927. 0.059976 and 0.055546 are the 2026 and 2028 rates, and exactly 5 percent applies only at or below 5,000 bopd.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which of these can appear in an Associate question only as a text to read and not as a number to compute?', '["The gas rate at a stated share.", "The royalty by price at a stated price.", "A marginal field''s liquids royalty rate.", "The terms of a lease that does not convert."]'::jsonb, 3, 'The terms of a lease that does not convert are concept-only: the engine models converted and new-acreage terms only, so they are taught from their text and never graded on a number. The gas rate, the royalty by price and a marginal field''s royalty are all computed by the engine''s rate functions and ledger.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 14, 'On the Regulations base, over its life Ekene Alpha pays a development levy of 35714217.371697 USD and a tertiary education tax of 0.000000. What explains the split?', '["Alpha is a shallow water lease, and the tertiary education tax is charged only onshore under the Act.", "Every Alpha year, 2026 to 2032, is a year under the Nigeria Tax Act 2025.", "Alpha states no prior-year opex, so the tertiary education tax has no base.", "The tertiary education tax is folded into companies income tax."]'::jsonb, 1, 'A year under the Nigeria Tax Act 2025 carries the development levy and no tertiary education tax, because NTA s.197(5) deletes that tax''s charging sections, and every Alpha year falls in 2026 or later. The education charge draws no line by terrain, the prior-year opex feeds HCDT, and the tertiary education tax is its own line in a year under the Act alone.'),
  ('pia', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does the fiscalPrice note on every PIA ledger tell the reader?', '["The fiscal price is the middle benchmark.", "The additional tax at the fiscal price is computed.", "The realised prices stand in for the Commission''s fiscal prices.", "The case''s fiscal price replaces the realised price."]'::jsonb, 2, 'The note reads: "The realised oil and condensate prices stand in for the Commission''s fiscal prices (PIA Seventh Schedule para 8), so the additional tax at the fiscal price (PIA s.268; NTA s.73) is not computed." The fiscal oil price is concept-only; it is not a benchmark, the additional tax is not computed, and the case carries no fiscal price.'),
  ('pia', 'beginner', 'final', null, 1, 'Which taxes does PIA s.259(a)(ii) add to the Service''s list, beside the hydrocarbon tax?', '["Royalties, rents and signature bonus, with their enforcement under the Act.", "The development levy and the NDDC levy on the total annual budget of each company.", "Companies income tax and tertiary education tax on taxable petroleum operations.", "Petroleum profits tax on leases that have not converted."]'::jsonb, 2, 'The text reads: "(ii) companies income tax and tertiary education tax in accordance with this Act as it relates to taxable petroleum operations". Royalties, rents and bonuses are the Commission''s under s.259(b)(i); the development levy comes from NTA s.59, years later, and the NDDC levy from the NDDC Act; and an unconverted lease sits outside the Act''s fiscal Part.'),
  ('pia', 'beginner', 'final', null, 2, 'Under NTA s.59(2), who collects the development levy, and where does it go first?', '["The Service, into a special account created for that purpose.", "The Commission, straight into the Federation Account with every royalty the lease pays.", "The Tertiary Education Trust Fund, which then passes shares to six other bodies.", "The Nigerian Sovereign Investment Authority."]'::jsonb, 0, 'The text reads: "(2) The Service shall collect the levy and pay it into a special account created for that purpose." The revenue is then shared under s.59(3), with 50% to the Tertiary Education Trust Fund, which receives a share and collects nothing. The Commission''s role is royalty, and the sovereign fund receives the royalty by price.'),
  ('pia', 'beginner', 'final', null, 3, 'Which companies do the closing words of NTA s.59(1) leave outside the development levy?', '["Every company in upstream or midstream gas operations, whatever its size or residence.", "Companies holding a deep offshore lease in a year under the Nigeria Tax Act 2025.", "Companies that already pay a tertiary education tax to the Service in the same year.", "Small companies and non-resident companies."]'::jsonb, 3, 'The text reads: "other than small companies and non-resident companies." The levy draws no line by gas operations or by terrain, and in the engine a year that carries the development levy carries no tertiary education tax.'),
  ('pia', 'beginner', 'final', null, 4, 'How does this course use the Finance Act 2023, and why?', '["It quotes it in full as a primary gazetted text, read on 2026-09-26 from the Official Gazette.", "It paraphrases it, because the copy read is a scan published by the Budget Office.", "It treats it as a secondary source, read only through law firm alerts and commentary on it.", "It leaves it out, as the Nigeria Tax Act 2025 repealed it."]'::jsonb, 1, 'The texts table lists the Finance Act 2023 as "Final Signed by PMB", published by the Budget Office of the Federation on 7 June 2023, a scanned copy read page by page: primary, paraphrased. The secondary source is the Finance Act 2021''s 2.5 percent, read through EY and Forvis Mazars alerts, and the course still uses the 2023 Act for the 3 percent rate and its effective date.'),
  ('pia', 'beginner', 'final', null, 5, 'Which phrase does the course reserve for a year of assessment the engine reads as "pia_only"?', '["A year under the Nigeria Tax Act 2025, which is 2026 onward under \"auto\".", "A year under the Act alone, before 2026 under \"auto\".", "A converted year.", "A stated reading of the framework, whichever year the learner types into the case box."]'::jsonb, 1, 'The vocabulary gives "a year under the Act alone" to a year of assessment the engine reads as "pia_only" (before 2026 under "auto"), and "a year under the Nigeria Tax Act 2025" to one it reads as "nta_2025". The course has no phrase "converted year", and a stated reading is the answer a run gives to one of the three open questions of the texts.'),
  ('pia', 'beginner', 'final', null, 6, 'What does the course say about the data in its Ekene teaching cases?', '["Every case, volume, price and cost is synthetic, written for this platform.", "The cases are anonymised records from a real Nigerian lease, with the names removed.", "Prices are the Commission''s fiscal prices for each year of the ledger.", "The volumes follow a real field and the costs are invented."]'::jsonb, 0, 'The course states that every Ekene case, field, volume, price and cost is synthetic, written for this platform, and that no real company, licence, field or price list appears. No record is anonymised, and the Commission''s fiscal price is concept-only: the realised price of the case stands in for it.'),
  ('pia', 'beginner', 'final', null, 7, 'Which rights does the Act''s producing instrument grant on an exclusive basis, in the words of s.70(1)(c)?', '["To carry out petroleum exploration operations over the acreage, shared with other licensees.", "To drill exploration and appraisal wells for up to 10 years in deep offshore acreage.", "To win, work, carry away and dispose of crude oil, condensates and natural gas.", "To take a royalty by price on crude oil from other holders."]'::jsonb, 2, 'Section 70(1)(c) grants a mining lease the right "to: (i) win, work, carry away and dispose of crude oil, condensates and natural gas on an exclusive basis". Shared exploration work belongs to the exploration licence, wells for appraisal to the prospecting licence, which in deep offshore may last up to 10 years under s.77(2), and a holder pays royalty to Government and takes none from anyone.'),
  ('pia', 'beginner', 'final', null, 8, 'How long does a petroleum exploration licence last under PIA s.71(3)?', '["A maximum of 20 years, including the development period of any discovery made on it.", "Not more than 10 years, with an initial period of five and an optional five-year extension.", "Until the conversion date of the oil prospecting licence it replaced under s.92(4).", "Three years, renewable for three more on prescribed conditions."]'::jsonb, 3, 'The text reads: "(3) A petroleum exploration licence shall be for three years and may be renewable for additional period of three years subject to fulfilment of prescribed conditions,". Twenty years is the mining lease (s.86(1)), ten years the deep offshore and frontier prospecting licence (s.77(2)), and the conversion date belongs to oil mining leases and oil prospecting licences.'),
  ('pia', 'beginner', 'final', null, 9, 'A converting holder keeps some acreage only to appraise a discovery. Under which instrument and fiscal terms does that acreage continue?', '["A petroleum prospecting licence, on the fiscal terms of s.267(b).", "Petroleum mining leases on the fiscal terms of s.267(a).", "Relinquished areas under s.93(4).", "Marginal fields under s.94(1)."]'::jsonb, 0, 'PIA s.93(6)(a) puts acreage designated under s.93(1)(a), (b), (c) or (2) "into a petroleum prospecting licence in accordance with section 78 of this Act", on the s.267(b) terms. Mining leases on s.267(a) terms are for developed or producing acreage, relinquishment under s.93(4) is for acreage nobody selects, and s.94(9) closes the door on new marginal fields.'),
  ('pia', 'beginner', 'final', null, 10, 'What may a holder do under PIA s.93(2) when its selected areas cover less than 40% of the oil mining lease?', '["Keep the whole lease on its old terms until it expires, with no areas relinquished at all.", "Select additional areas of the lease for conversion to a petroleum prospecting licence.", "Claim a production allowance on the unselected areas until the conversion date passes.", "Declare the unselected areas marginal fields."]'::jsonb, 1, 'The text reads: "(2) Where the total acreage selected under subsection (1) is less than 40% of the area to which the applicable oil mining lease applies, the holder may select additional areas covered by the oil mining lease for conversion to a petroleum prospecting licence". Areas left unselected are relinquished under s.93(4), the subsection grants no allowance, and no new marginal fields may be declared.'),
  ('pia', 'beginner', 'final', null, 11, 'For leases under NTA Chapter Three Parts II and III, what gas royalty does Seventh Schedule Part IV para 7(3)(c) set, and does the engine compute it?', '["5% everywhere and 2.5% for gas used in-country, computed by the gas royalty function on every case.", "7% onshore and 5% offshore, computed whenever pia_lease_status is stated as \"converted\".", "7% onshore and 5% offshore; concept-only, as the engine models converted and new leases alone.", "12.5% in shallow water and 15% onshore, the terrain rates."]'::jsonb, 2, 'Para 7(3)(c) sets natural gas royalty for those leases at "(i) onshore areas: 7 %, and (ii) offshore areas: 5%". The engine models converted and new-acreage terms only and computes no royalty for those leases, so the provision is concept-only. The 5 and 2.5 percent gas rates belong to para 10(6) of the Act, and a converted lease is under the Act''s terms.'),
  ('pia', 'beginner', 'final', null, 12, 'What does NTA s.90(1) apply its Part on petroleum profits tax to?', '["Oil prospecting licences and oil mining leases that are yet to convert under the Act.", "Petroleum mining leases granted out of new acreage after the Nigeria Tax Act 2025.", "Deep offshore leases in a year under the Nigeria Tax Act 2025.", "Every lease in a year of assessment read as nta_2025."]'::jsonb, 0, 'The text reads: "90. (1) This Part shall apply to oil prospecting licences and oil mining petroleum leases that are yet to convert under the provisions of the Petroleum Industry" Act. So an unconverted lease pays petroleum profits tax under the Nigeria Tax Act from its commencement, on the old royalty terms; the engine models converted and new-acreage terms only, so this is concept-only. New leases, deep offshore leases and other leases in NTA years sit under the hydrocarbon tax Part.'),
  ('pia', 'beginner', 'final', null, 13, 'At 7500 bopd, which rates does the engine return for onshore, deep offshore and frontier?', '["0.058333 onshore, 0.058333 deep offshore, and 0.058333 frontier, as the small-field tranches apply in every terrain.", "0.058333 onshore, 0.050000 deep offshore and 0.075000 frontier.", "0.075000 onshore, 0.050000 deep offshore and 0.075000 frontier.", "0.050000 in all three, the first tranche."]'::jsonb, 1, 'Onshore at 7500 bopd blends 5 percent on the first 5,000 bopd and 7.5 percent on the rest: 0.058333. Deep offshore pays exactly 5 percent up to and including 50,000 bopd, and frontier pays 7.5 percent at every rate. The small-field tranches are for onshore and shallow water only, and the first tranche covers only the first 5,000 bopd.'),
  ('pia', 'beginner', 'final', null, 14, 'Onshore and shallow water fields both produce 120000 bopd. How do their weighted royalty rates compare?', '["15 percent onshore and 12.5 percent in shallow water, the two terrain rates of para 10(2) on the whole volume.", "0.119792 onshore and 0.142708 in shallow water.", "0.142708 onshore and 0.119792 in shallow water.", "0.064583 in both terrains."]'::jsonb, 2, 'Above 10,000 bopd the barrels past the edge pay the terrain rate, so the weighted rate climbs toward 15 percent onshore and 12.5 percent in shallow water without reaching either: 0.142708 and 0.119792 at 120000 bopd. The flat terrain rates ignore the tranches, the reversed pair swaps the terrains, and 0.064583 is the deep offshore rate at that daily rate.'),
  ('pia', 'beginner', 'final', null, 15, 'What royalty rate does r.13(1)(b) give deep offshore acreage producing 120000 bopd?', '["0.064583: 5 percent on 50,000 bopd and 7.5 percent on the rest, divided by the total.", "7.5 percent, the terrain rate, since most of the barrels lie above the 50,000 bopd tier.", "0.119792, the rate the shallow water scale returns at the same daily rate.", "0.054167, the rate at 60,000 bopd."]'::jsonb, 0, 'Regulations r.13(1)(b) makes the deep offshore rate "a weighted average rate of 5% of 50,000bopd plus 7.5% of the incremental daily production above 50,000bopd divided by the total production per day": 0.064583 at 120000 bopd. The flat 7.5 percent ignores the first tier, 0.119792 is shallow water and 0.054167 is the rate at 60,000 bopd.'),
  ('pia', 'beginner', 'final', null, 16, 'What does the engine return just below the second edge, at 9999 bopd onshore?', '["0.062500, the rate at exactly 10,000 bopd, which holds for the whole band below it as well.", "0.058333, the rate at 7500 bopd, which holds from there up to the edge of the second tranche.", "0.075000, the second tranche''s rate on every barrel.", "0.062499."]'::jsonb, 3, 'The rate is a weighted blend that rises barrel by barrel: 0.062499 at 9999 bopd and 0.062500 at exactly 10,000 bopd. It does not hold flat across a band, and 7.5 percent reaches only the barrels between 5,000 and 10,000 bopd while the first 5,000 pay 5 percent.'),
  ('pia', 'beginner', 'final', null, 17, 'Which rates does the engine return for gas when 40 percent and when 60 percent of it is used in-country?', '["0.035000 at 40 percent and 0.040000 at 60 percent, since more gas used in-country raises the rate.", "0.025000 at both shares, since any in-country use earns the lower rate on all the gas.", "0.040000 at 40 percent and 0.035000 at 60 percent.", "0.050000 at both shares."]'::jsonb, 2, 'Each point of in-country share moves the blend from 5 toward 2.5 percent, so a larger share gives a smaller rate: the engine returns 0.040000 at 40 and 0.035000 at 60. Reversing them gets the direction wrong, 0.025000 is reached only when all the gas stays in Nigeria, and 0.050000 is the rate with none of it used in-country.'),
  ('pia', 'beginner', 'final', null, 18, 'Gas sold abroad: what production royalty rate does Regulations r.16(5) set on it?', '["It pays 2.5%, the rate that para 10(6) gives to gas, wherever the gas is finally used.", "It pays production royalty at 5% of the chargeable volumes.", "It pays the terrain rate of the field it comes from, as the liquids do under para 10(2).", "It pays no royalty, as exported gas is outside the Act."]'::jsonb, 1, 'The text reads: "(5) The royalty based on production of natural gas for export shall be at a rate of 5% of the chargeable volumes". The 2.5% rate is only for gas produced and utilised in-country, gas pays no terrain rate, and exported gas is charged.'),
  ('pia', 'beginner', 'final', null, 19, 'Which figure does Alpha''s 2029 row carry in the liquids royalty rate column, at 5669.846575 bopd?', '["0.050000, since the field is within a few hundred barrels of the first edge and rounds down to it.", "0.062500, the rate at the upper edge of the small-field band that Alpha sits in.", "0.055546, the rate of 2028, held until the field drops below 5,000 bopd.", "0.052954."]'::jsonb, 3, 'In 2029 Alpha is still above 5,000 bopd, so its weighted rate blends in a little of the 7.5 percent tranche: 0.052954. The engine does not round a daily rate to an edge, 0.062500 applies only at 10,000 bopd, and each year reads its own daily rate, so 2028''s 0.055546 does not carry over.'),
  ('pia', 'beginner', 'final', null, 20, 'What does the engine do with a daily rate of -1 handed to deriveOilRoyaltyRate?', '["It refuses: the crude oil and condensate daily rate must be a finite number of 0 or more; got -1.", "It returns 0.050000, the first tranche rate, as it does for every daily rate at or below 5,000 bopd.", "It returns a negative royalty rate.", "It clamps the rate to 0 bopd and adds a note."]'::jsonb, 0, 'The refusal reads, in the engine''s own words: The crude oil and condensate daily rate must be a finite number of 0 or more; got -1. A refusal returns no rate at all. The engine does not read a negative daily rate as a small one, does not return a negative rate and does not clamp a bad input behind a note.'),
  ('pia', 'beginner', 'final', null, 21, 'Which levels does the Regulations reading hold for 2020, a year before its base year?', '["Levels deflated backwards by 2 percent a year from the 2021 base.", "50.000000, 100.000000 and 150.000000, the base levels, held until the base year.", "51.000000, 102.000000 and 153.000000, the first escalation.", "No benchmarks: 2020 is outside the Regulations."]'::jsonb, 1, 'Before its base year each base keeps 50, 100 and 150, so the Regulations base returns 50.000000, 100.000000 and 150.000000 for 2020 as for 2021. Neither text deflates backwards, 51.000000, 102.000000 and 153.000000 are the Regulations'' 2022 levels (and the Act''s 2021), and the engine returns benchmarks for any year.'),
  ('pia', 'beginner', 'final', null, 22, 'At 170 USD/bbl in 2025, what royalty by price rate does each base return?', '["0.100000 on the Regulations base and 0.097057 on the Act base, whose high benchmark is higher.", "More than 10 percent on the Regulations base, as the line keeps rising past the high benchmark.", "0.050000 on each, the middle benchmark rate.", "0.100000 on each."]'::jsonb, 3, 'At or above the high benchmark of both bases the rate is 10 percent: 170 is above 162.360000 and 165.610000, so both bases return 0.100000. 0.097057 is the Act base at 162.360000, where the Act''s own high benchmark is not yet reached; the rate does not rise past 10 percent; and 5 percent sits at the middle benchmark.'),
  ('pia', 'beginner', 'final', null, 23, 'Price 120, year 2025: set the two base-year readings side by side. What do they return?', '["0.060865 with the Regulations, 0.058694 with the Act.", "0.058694 with the Regulations base and 0.060865 with the Act base, since the Act''s benchmarks are higher.", "0.060865 on both, since the two readings agree above the middle benchmark of each base.", "0.100000 on both bases."]'::jsonb, 0, 'The engine returns 0.060865 on the Regulations base and 0.058694 on the Act base: the Act''s higher benchmarks put 120 lower on its scale, so the Act base charges less. The readings differ between the benchmarks, and 120 is below both high benchmarks of 2025.'),
  ('pia', 'beginner', 'final', null, 24, 'What total royalty, production royalty and royalty by price together, does the 95 and 88 USD/bbl case return under each base-year reading?', '["69663505.866593 USD on either base, since only the royalty by price depends on the base and it is the same.", "69663505.866593 USD under the Regulations and 68707857.789855 USD under the Act.", "20694235.033259 USD on the Regulations base, the total royalty of the year.", "68707857.789855 USD on the Regulations base, and 69663505.866593 USD on the Act base."]'::jsonb, 1, 'The engine returns a total royalty of 69663505.866593 USD on the Regulations base and 68707857.789855 USD on the Act base. The production royalty is the same on both, but the royalty by price differs, so the totals differ; 20694235.033259 USD is the Regulations base royalty by price alone; and the reversed pair swaps the bases.'),
  ('pia', 'beginner', 'final', null, 25, 'Regulations r.15(2) names a price as the basis of the royalty by price. Which price, and what stands in for it in the engine?', '["The daily rate of crude oil and condensate, which the engine reads as the year over its calendar days.", "The Commission''s fiscal oil price, which the case states and the engine reads for every year.", "Last year''s average price.", "The fiscal oil price; the engine uses the realised price and says so in a note."]'::jsonb, 3, 'r.15(2) reads: "(2) The royalty by price shall be based on the fiscal oil price for crude oil". The fiscal oil price the Commission sets is concept-only: the realised prices stand in for it, and the engine''s note says so. The royalty by price reads price alone, the case carries no fiscal price, and nothing is carried from the previous year.'),
  ('pia', 'beginner', 'final', null, 26, 'From when does each text escalate the royalty by price levels?', '["The Act from the beginning of 2021; the Regulations from 1 January 2022.", "Both from 1 January 2021, since the Regulations adopt the Act''s own escalation date unchanged.", "Both from 1 January 2026, the first year of the Nigeria Tax Act 2025.", "The Regulations from 2021 and the Act from 2022."]'::jsonb, 0, 'The Act raises the levels "at the beginning of 2021 and of each succeeding calendar year", and the Regulations'' Schedule escalates "commencing 1st January 2022". That one-year gap is the open reading of the base year. The Nigeria Tax Act 2025 restates the Act''s wording and moves no date, and reversing the two dates reverses the texts.'),
  ('pia', 'beginner', 'final', null, 27, 'Ekene Alpha''s 2027 HCDT is 720000.000000 USD. What produced it?', '["3 percent of the year''s own opex and capex, the total annual budget that also sets the NDDC levy.", "3 percent of 2026''s opex of 24000000 USD.", "A fixed contribution the case states for every year after the first one.", "3 percent of the 2027 revenue from crude oil and condensate."]'::jsonb, 1, 'From its second year the engine reads the ledger''s own previous opex for HCDT. Alpha spent 24000000 USD of opex in 2026, and 3 percent of it is 720000.000000 USD in 2027, as PIA s.240(2) sets. The budget of opex plus capex belongs to the NDDC levy, Alpha states no fixed contribution, and no revenue enters the HCDT base.'),
  ('pia', 'beginner', 'final', null, 28, 'Which of Alpha''s 2027 rows set its 1620000.000000 USD NDDC charge on the default base?', '["The 2026 opex of 24000000 USD alone, the preceding year''s cost, which is the base HCDT reads as well.", "The year''s gross revenue from crude oil, condensate and associated gas, at 3 percent of the total.", "Capex of 30000000 USD alone.", "Opex of 24000000 and capex of 30000000 USD."]'::jsonb, 3, 'The default NDDC base is the total annual budget, the year''s opex plus capex (from a secondary source): 3 percent of 24000000 plus 30000000 USD gives 1620000.000000 USD. Preceding-year opex is the HCDT base, revenue is no part of the levy, and capex alone leaves out the opex the budget counts.'),
  ('pia', 'beginner', 'final', null, 29, 'What does PIA s.257(1) say about the settlor''s annual host communities trust payment?', '["It is deductible for the hydrocarbon tax and companies income tax as applicable.", "It is deductible for companies income tax only, and is added back in the hydrocarbon tax base.", "It is paid out of the royalty and so is never deducted.", "It replaces the NDDC levy in years under the Act."]'::jsonb, 0, 'The text reads that the payment "shall be deductible for the purposes of hydrocarbon tax and companies" income tax. It is deductible in both bases (in the hydrocarbon tax at the crude-plus-condensate share), it is a contribution separate from royalty, and the NDDC levy is charged beside it under its own Act.'),
  ('pia', 'beginner', 'final', null, 30, 'Which contributions does PIA s.263(1)(h) let a company deduct for hydrocarbon tax?', '["Tertiary education tax and companies income tax.", "Royalties on crude oil and associated gas alone.", "Amounts paid to host communities trusts, the Environmental Remediation Fund, the NDDC and similar approved funds.", "The development levy under NTA s.59."]'::jsonb, 2, 'Section 263(1)(h) covers "any amount contributed to any fund, scheme or arrangement approved by the Commission pursuant to the establishment of host communities development trusts under Chapter 3 of this Act, Environmental Remediation Fund, Niger Delta Development Commission and other similar contributions." The profit taxes are barred by s.264(l), royalties are deductible under a different paragraph, s.263(1)(b), and the development levy is never charged on hydrocarbon tax profits.'),
  ('pia', 'beginner', 'final', null, 31, 'The gas field ekene_nag_gas_in_country_half returns a 2026 hydrocarbon tax of 0.000000 and companies income tax of 10713000.000000 USD. Why?', '["Half its gas is used in-country, and the in-country share exempts a field from the hydrocarbon tax entirely.", "It sells no crude oil or condensate, the only products that tax charges, while income tax reads gas profit.", "Shallow water gas fields sit outside the hydrocarbon tax in every framework by PIA s.260(3).", "Its gas royalty is deducted in full, so no profit is left."]'::jsonb, 1, 'The hydrocarbon tax charges crude oil and condensate only, so a field with none pays no hydrocarbon tax, while companies income tax is charged on the whole oil and gas profit, 10713000.000000 USD in 2026. The in-country share moves only the gas royalty, s.260(3) concerns frontier and deep offshore, and the field still shows a companies income tax profit.'),
  ('pia', 'beginner', 'final', null, 32, 'The worked example states an NDDC sum of 15000000 USD. What does the engine do with it?', '["Adds it to 3 percent of the total annual budget, and charges the two together as the year''s NDDC levy.", "Ignores it, since the levy is always 3 percent of the total annual budget under the NDDC Act.", "Uses it as the prior-year opex for HCDT.", "Uses it in place of the percentage."]'::jsonb, 3, 'A fixed sum in pia_nddc_levy_fixed_usd replaces the percentage when given, so the worked example''s NDDC line is 15000000.000000 USD. Nothing is added on top, the engine applies the stated sum, and HCDT reads the separately stated prior-year opex of 170000000 USD.'),
  ('pia', 'beginner', 'final', null, 33, 'On the Regulations base, which seven lines add up to Ekene Alpha''s government cash flow of 556475163.954050 USD?', '["Royalties, hydrocarbon tax, income tax, education tax, development levy, HCDT and NDDC.", "Royalties, hydrocarbon tax, income tax, capex, opex, HCDT and NDDC.", "The three royalty lines and the four taxes, with HCDT left out.", "Hydrocarbon tax alone, over the life."]'::jsonb, 0, 'The decomposition sums total royalties, the hydrocarbon tax, companies income tax, the tertiary education tax (0 on Alpha), the development levy, HCDT and the NDDC levy to 556475163.954050 USD. Capex and opex are the project''s own costs; HCDT and the NDDC levy sit on the government side of the take; and the hydrocarbon tax is one line of seven.'),
  ('pia', 'beginner', 'final', null, 34, 'On the Regulations base, which development levy does Ekene Alpha pay over its life at a 50 percent working interest?', '["35714217.371697 USD, as the levy is charged at field level before any working interest share.", "A quarter of the 100 percent figure, since the levy halves twice.", "17857108.685849 USD, half the 100 percent figure.", "The same share of profit at a lower rate."]'::jsonb, 2, 'Every money line is scaled to the working interest share after the field-level arithmetic, so at 50 percent the development levy is 17857108.685849 USD against 35714217.371697 USD at 100 percent. The engine reports money at the share, it halves once, and the 4 percent rate is unchanged.'),
  ('pia', 'beginner', 'final', null, 35, 'What does the shared wording call government cash flow over revenue less opex, with capex added back?', '["Government take, the engine''s kpis.government_take_pct, read undiscounted over the life of the lease.", "The government share of net revenue, a second metric.", "The effective royalty rate of the lease.", "The pre-take net cash flow of the project."]'::jsonb, 1, 'fiscalConventions.js defines "Government share of net revenue" as "Government cash flow divided by revenue less opex over the project life, so capex is added back to the contractor side." Government take divides by revenue less opex less capex; royalty is only one part of government cash flow; and the pre-take net cash flow is the take''s denominator.'),
  ('pia', 'beginner', 'final', null, 36, 'The government take is undiscounted and nominal. What follows for a dollar of tax paid in 2032 against one paid in 2026?', '["The 2032 dollar counts for less, discounted at the case''s 10 percent nominal rate to the base year.", "The 2032 dollar counts for more, escalated by 2 percent a year as the benchmarks are.", "Only the first year is read, so the 2032 dollar is left out of the take.", "Both count the same."]'::jsonb, 3, 'The engine''s take sums the whole life undiscounted and nominal, so a dollar in 2032 counts the same as a dollar in 2026. The 10 percent discount rate serves NPV, the 2 percent escalation belongs to the royalty by price benchmarks, and the take reads every year of the ledger.'),
  ('pia', 'beginner', 'final', null, 37, 'Which three questions does this course call open readings?', '["The royalty by price base year, the new-lease rate onshore or in shallow water, and the deep offshore rate under the NTA.", "The terrain of a field in two terrains, the fiscal oil price and the terms of leases that do not convert.", "The NDDC levy base, the tertiary education tax before 2023 and the Act''s effective date.", "The daily rate reading, the shared costs and the take."]'::jsonb, 0, 'The three open readings are the questions the texts leave open: the royalty by price base year, the hydrocarbon tax rate of a new lease onshore or in shallow water, and the deep offshore hydrocarbon tax under the Nigeria Tax Act 2025. The first distractor lists concept-only provisions, the second lists values from secondary sources and a date, and the third lists the engine''s stated notes and a metric.'),
  ('pia', 'beginner', 'final', null, 38, 'What does the course mean when it calls an input a stated reading?', '["The reading of a text the course judges to be the law after comparing the Act with the Regulations.", "Any figure the engine prints in kpis.pia_notes below the table of a run.", "The answer to an open reading that a run states as an input.", "The Regulations'' reading of any provision."]'::jsonb, 2, 'The vocabulary defines a stated reading as the answer to an open reading that a run states as an input, and it is never presented as the law. A note in kpis.pia_notes is the engine''s statement about a default, a conflict or an approximation, and the Regulations'' base year is only one of two readings of one question.'),
  ('pia', 'beginner', 'final', null, 39, 'When this course says royalty with no qualifier, what does it mean?', '["Any payment a lease makes to the state, taxes and contributions included, over its life.", "The production royalty on liquids and gas plus the royalty by price, the engine''s total royalty.", "The production royalty on crude oil and condensate alone, leaving out gas and price.", "The royalty by price, the Act''s newest royalty."]'::jsonb, 1, 'The vocabulary fixes royalty as the production royalty on liquids and gas plus the royalty by price, the engine''s total royalty, and asks a writer to name the part when only one is meant. Taxes and contributions are separate lines, and the gas royalty and royalty by price are both inside royalty.'),
  ('pia', 'beginner', 'final', null, 40, 'Why can a partner''s working interest share never move the tranche a field falls into?', '["The share is applied to the daily rate before the tranches are read, so every partner''s rate is the same.", "The tranches read the price, which the working interest share does not scale in any year.", "Regulations set one tranche for every partner by law.", "Rates are read at field level first."]'::jsonb, 3, 'The engine reads the tranches, the caps and every rate at field level, then scales every money line to the share, so the daily rate and its rate are the field''s whatever the share. Applying the share to the daily rate first would move the tranche, the tranches read volume, and no text assigns tranches to partners.'),
  ('pia', 'beginner', 'final', null, 41, 'What does the engine say when a case arrives with no production rows at all?', '["No production data found. Upload and process a CSV first.", "It returns a ledger of zeros with a note in kpis.pia_notes saying that no production was stated.", "A run on the golden rows of Ekene Alpha.", "It refuses with a note naming the missing terrain."]'::jsonb, 0, 'computeCashFlow refuses a case with no production rows, in its own words: No production data found. Upload and process a CSV first. A refusal returns no ledger and no note, the engine never substitutes another case''s rows, and the message concerns the rows, whatever the terrain.'),
  ('pia', 'beginner', 'final', null, 42, 'Para 10(3) gives deep offshore production of not more than 50,000 bopd a month 5%. What does the engine return at exactly that edge?', '["0.054167, since the 50,000th barrel falls in the 7.5 percent tier above the edge.", "7.5 percent, the deep offshore terrain rate of para 10(2), charged on every barrel.", "0.050000, since the edge belongs to the 5 percent tier.", "0.112500, the rate of a field at that daily rate."]'::jsonb, 2, 'Para 10(3) reads: "(3) For deep offshore fields with a production during a month of not more than 50,000 bopd, the royalty rate shall be 5%". At exactly 50,000 bopd the engine returns 0.050000; 0.054167 is its rate at 60,000 bopd, the 7.5 percent reaches only barrels past 50,000, and 0.112500 is the shallow water rate at 50,000 bopd.');
